export type EventCallback = (payload: any) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventCallback>> = new Map();

  publish(event: string, payload: any): void {
    const subs = this.subscribers.get(event);
    if (!subs || subs.size === 0) return;
    // Deliver synchronously for simplicity
    for (const cb of subs) {
      try {
        cb(payload);
      } catch (err) {
        // Swallow subscriber errors to avoid breaking other subscribers
        // In a real system, we'd log this
      }
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event)!.add(callback);
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private store: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const user: User = { id: randomUUID(), name: input.name, email: input.email };
    this.store.set(user.id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.store.get(id);
  }

  getAll(): User[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...input, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private store: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const project: Project = { id: randomUUID(), name: input.name, description: input.description, memberIds: [] };
    this.store.set(project.id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.store.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<Project, 'id' | 'memberIds'>>): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...input, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  addMember(id: string, userId: string): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    if (!existing.memberIds.includes(userId)) {
      existing.memberIds.push(userId);
      this.store.set(id, existing);
    }
    return existing;
  }

  removeMember(id: string, userId: string): Project | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    existing.memberIds = existing.memberIds.filter((m) => m !== userId);
    this.store.set(id, existing);
    return existing;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private store: Map<string, Task> = new Map();
  constructor(private bus: EventBus) {}

  create(input: { title: string; description: string; projectId: string; assigneeId?: string | null }): Task {
    const task: Task = {
      id: randomUUID(),
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: input.assigneeId ?? null,
      projectId: input.projectId,
    };
    this.store.set(task.id, task);
    if (task.assigneeId) {
      this.bus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId });
    }
    return task;
  }

  getById(id: string): Task | undefined {
    return this.store.get(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.store.values()).filter((t) => t.projectId === projectId);
  }

  getAll(): Task[] {
    return Array.from(this.store.values());
  }

  update(id: string, input: Partial<Omit<Task, 'id' | 'status' | 'projectId'>>): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...input, id };
    this.store.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }

  assign(id: string, assigneeId: string | null): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    existing.assigneeId = assigneeId;
    this.store.set(id, existing);
    if (assigneeId) {
      this.bus.publish('task.assigned', { taskId: existing.id, taskTitle: existing.title, assigneeId });
    }
    return existing;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    const oldStatus = existing.status;
    if (!this.isForwardTransition(oldStatus, newStatus)) {
      return undefined;
    }
    existing.status = newStatus;
    this.store.set(id, existing);
    this.bus.publish('task.statusChanged', {
      taskId: existing.id,
      taskTitle: existing.title,
      assigneeId: existing.assigneeId,
      oldStatus,
      newStatus,
    });
    return existing;
  }

  private isForwardTransition(oldStatus: TaskStatus, newStatus: TaskStatus): boolean {
    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    return order.indexOf(newStatus) >= order.indexOf(oldStatus);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export class CommentService {
  private store: Map<string, Comment> = new Map();
  constructor(private bus: EventBus) {}

  create(input: { taskId: string; authorId: string; body: string; taskTitle?: string; authorName?: string }): Comment {
    const comment: Comment = {
      id: randomUUID(),
      taskId: input.taskId,
      authorId: input.authorId,
      body: input.body,
      createdAt: new Date().toISOString(),
    };
    this.store.set(comment.id, comment);
    // Publish event for notifications. Title/name may not be known; router can enrich, but spec forbids service-to-service reads.
    this.bus.publish('comment.added', {
      commentId: comment.id,
      taskId: comment.taskId,
      taskTitle: input.taskTitle ?? '(unknown task)',
      authorId: comment.authorId,
      authorName: input.authorName ?? '(unknown user)'
    });
    return comment;
  }

  getById(id: string): Comment | undefined {
    return this.store.get(id);
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.store.values()).filter((c) => c.taskId === taskId);
  }

  delete(id: string): boolean {
    return this.store.delete(id);
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

export class NotificationService {
  private store: Map<string, Notification> = new Map();

  constructor(private bus: EventBus) {
    // Subscribe to events
    this.bus.subscribe('task.assigned', (p: { taskId: string; taskTitle: string; assigneeId: string }) => {
      const message = `You were assigned to task "${p.taskTitle}" (${p.taskId})`;
      this.create(p.assigneeId, message);
    });

    this.bus.subscribe(
      'task.statusChanged',
      (p: { taskId: string; taskTitle: string; assigneeId: string | null; oldStatus: string; newStatus: string }) => {
        if (p.assigneeId) {
          const message = `Task "${p.taskTitle}" (${p.taskId}) moved from ${p.oldStatus} to ${p.newStatus}`;
          this.create(p.assigneeId, message);
        }
      }
    );

    this.bus.subscribe(
      'comment.added',
      (p: { commentId: string; taskId: string; taskTitle: string; authorId: string; authorName: string }) => {
        // We don't have access to task assignee here; per spec, notification is for task assignee.
        // To respect boundaries, we will allow router to pass enriched events with an additional assigneeId if available.
        // If not provided, we cannot deliver.
        const anyPayload = p as any;
        const assigneeId: string | undefined = anyPayload.assigneeId;
        if (assigneeId) {
          const message = `${p.authorName} commented on task "${p.taskTitle}": comment ${p.commentId}`;
          this.create(assigneeId, message);
        }
      }
    );
  }

  private create(userId: string, message: string): Notification {
    const notif: Notification = {
      id: randomUUID(),
      userId,
      message,
      read: false,
      createdAt: new Date().toISOString(),
    };
    this.store.set(notif.id, notif);
    return notif;
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.store.values())
      .filter((n) => n.userId === userId)
      .sort((a, b) => a.createdAt.localeCompare(b.createdAt));
  }

  markAsRead(id: string): Notification | undefined {
    const existing = this.store.get(id);
    if (!existing) return undefined;
    existing.read = true;
    this.store.set(id, existing);
    return existing;
  }
}

import http, { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { EventBus } from './event-bus';
import { UserService } from './services/user-service';
import { ProjectService } from './services/project-service';
import { TaskService, Task } from './services/task-service';
import { CommentService } from './services/comment-service';
import { NotificationService } from './services/notification-service';

function parseBody(req: IncomingMessage): Promise<any> {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => (data += chunk));
    req.on('end', () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch (e) {
        reject(new Error('Invalid JSON'));
      }
    });
    req.on('error', reject);
  });
}

function send(res: ServerResponse, status: number, body: any) {
  const text = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(text) });
  res.end(text);
}

export class ApiRouter {
  private server?: http.Server;
  constructor(
    private bus: EventBus,
    private users: UserService,
    private projects: ProjectService,
    private tasks: TaskService,
    private comments: CommentService,
    private notifs: NotificationService
  ) {
    // Enrich comment.added events with assigneeId by observing the bus and the task store via the router.
    // Since services cannot call each other, the router listens and republishes with assigneeId when possible.
    this.bus.subscribe('comment.added', (p: any) => {
      const task: Task | undefined = this.tasks.getById(p.taskId);
      if (task && task.assigneeId) {
        const enriched = { ...p, assigneeId: task.assigneeId };
        this.bus.publish('comment.added', enriched); // Publish enriched event; NotificationService will act on it
      }
    });
  }

  start(port: number): Promise<void> {
    this.server = http.createServer(async (req, res) => {
      try {
        await this.route(req, res);
      } catch (err: any) {
        send(res, 500, { error: 'Internal Server Error', details: err?.message });
      }
    });
    return new Promise((resolve) => this.server!.listen(port, resolve));
  }

  stop(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.server) return resolve();
      this.server.close((err) => (err ? reject(err) : resolve()));
    });
  }

  private async route(req: IncomingMessage, res: ServerResponse) {
    const url = new URL(req.url || '/', 'http://localhost');
    const method = req.method || 'GET';

    // Users
    if (method === 'GET' && url.pathname === '/users') {
      return send(res, 200, this.users.getAll());
    }
    if (method === 'POST' && url.pathname === '/users') {
      const body = await parseBody(req);
      const created = this.users.create({ name: body.name, email: body.email });
      return send(res, 201, created);
    }
    if (method === 'GET' && url.pathname.startsWith('/users/')) {
      const id = url.pathname.split('/')[2];
      const user = this.users.getById(id);
      if (!user) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, user);
    }
    if (method === 'PUT' && url.pathname.startsWith('/users/')) {
      const id = url.pathname.split('/')[2];
      const body = await parseBody(req);
      const updated = this.users.update(id, { name: body.name, email: body.email });
      if (!updated) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, updated);
    }
    if (method === 'DELETE' && url.pathname.startsWith('/users/')) {
      const id = url.pathname.split('/')[2];
      const ok = this.users.delete(id);
      return send(res, ok ? 204 : 404, ok ? {} : { error: 'Not Found' });
    }

    // Projects
    if (method === 'GET' && url.pathname === '/projects') {
      return send(res, 200, this.projects.getAll());
    }
    if (method === 'POST' && url.pathname === '/projects') {
      const body = await parseBody(req);
      const created = this.projects.create({ name: body.name, description: body.description });
      return send(res, 201, created);
    }
    if (method === 'GET' && url.pathname.startsWith('/projects/')) {
      const [, , id, rest] = url.pathname.split('/');
      if (!id || rest) {
        // Could be nested routes like /projects/:id/members
      } else {
        const proj = this.projects.getById(id);
        if (!proj) return send(res, 404, { error: 'Not Found' });
        return send(res, 200, proj);
      }
    }
    if (method === 'PUT' && url.pathname.match(/^\/projects\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const body = await parseBody(req);
      const updated = this.projects.update(id, { name: body.name, description: body.description });
      if (!updated) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, updated);
    }
    if (method === 'DELETE' && url.pathname.match(/^\/projects\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const ok = this.projects.delete(id);
      return send(res, ok ? 204 : 404, ok ? {} : { error: 'Not Found' });
    }
    if (url.pathname.match(/^\/projects\/[^/]+\/members$/)) {
      const id = url.pathname.split('/')[2];
      if (method === 'POST') {
        const body = await parseBody(req);
        const updated = this.projects.addMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not Found' });
        return send(res, 200, updated);
      }
      if (method === 'DELETE') {
        const body = await parseBody(req);
        const updated = this.projects.removeMember(id, body.userId);
        if (!updated) return send(res, 404, { error: 'Not Found' });
        return send(res, 200, updated);
      }
    }

    // Tasks
    if (method === 'GET' && url.pathname === '/tasks') {
      const projectId = url.searchParams.get('projectId');
      if (projectId) return send(res, 200, this.tasks.getByProject(projectId));
      return send(res, 200, this.tasks.getAll());
    }
    if (method === 'POST' && url.pathname === '/tasks') {
      const body = await parseBody(req);
      const created = this.tasks.create({
        title: body.title,
        description: body.description,
        projectId: body.projectId,
        assigneeId: body.assigneeId ?? null,
      });
      return send(res, 201, created);
    }
    if (method === 'GET' && url.pathname.match(/^\/tasks\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const task = this.tasks.getById(id);
      if (!task) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, task);
    }
    if (method === 'PUT' && url.pathname.match(/^\/tasks\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const body = await parseBody(req);
      const updated = this.tasks.update(id, { title: body.title, description: body.description, assigneeId: body.assigneeId });
      if (!updated) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, updated);
    }
    if (method === 'DELETE' && url.pathname.match(/^\/tasks\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const ok = this.tasks.delete(id);
      return send(res, ok ? 204 : 404, ok ? {} : { error: 'Not Found' });
    }
    if (method === 'PUT' && url.pathname.match(/^\/tasks\/[^/]+\/status$/)) {
      const id = url.pathname.split('/')[2];
      const body = await parseBody(req);
      const updated = this.tasks.changeStatus(id, body.newStatus);
      if (!updated) return send(res, 400, { error: 'Invalid status transition or task not found' });
      return send(res, 200, updated);
    }
    if (method === 'PUT' && url.pathname.match(/^\/tasks\/[^/]+\/assign$/)) {
      const id = url.pathname.split('/')[2];
      const body = await parseBody(req);
      const updated = this.tasks.assign(id, body.assigneeId ?? null);
      if (!updated) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, updated);
    }

    // Comments
    if (method === 'GET' && url.pathname === '/comments') {
      const taskId = url.searchParams.get('taskId');
      if (!taskId) return send(res, 400, { error: 'taskId required' });
      return send(res, 200, this.comments.getByTask(taskId));
    }
    if (method === 'POST' && url.pathname === '/comments') {
      const body = await parseBody(req);
      const task = this.tasks.getById(body.taskId);
      const user = this.users.getById(body.authorId);
      const created = this.comments.create({
        taskId: body.taskId,
        authorId: body.authorId,
        body: body.body,
        taskTitle: task?.title,
        authorName: user?.name,
      });
      return send(res, 201, created);
    }
    if (method === 'GET' && url.pathname.match(/^\/comments\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const c = this.comments.getById(id);
      if (!c) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, c);
    }
    if (method === 'DELETE' && url.pathname.match(/^\/comments\/[^/]+$/)) {
      const id = url.pathname.split('/')[2];
      const ok = this.comments.delete(id);
      return send(res, ok ? 204 : 404, ok ? {} : { error: 'Not Found' });
    }

    // Notifications
    if (method === 'GET' && url.pathname === '/notifications') {
      const userId = url.searchParams.get('userId');
      if (!userId) return send(res, 400, { error: 'userId required' });
      return send(res, 200, this.notifs.getByUser(userId));
    }
    if (method === 'PUT' && url.pathname.match(/^\/notifications\/[^/]+\/read$/)) {
      const id = url.pathname.split('/')[2];
      const updated = this.notifs.markAsRead(id);
      if (!updated) return send(res, 404, { error: 'Not Found' });
      return send(res, 200, updated);
    }

    // Fallback
    send(res, 404, { error: 'Not Found' });
  }
}

